22	// 如此；不能挑第一份或最后一份继续，不能合并、删除重复项或重新计算结果后
23	// 掩盖冲突。被拒绝的操作保留原文件、不留业务变更、不占用新的请求编号。
24	
25	// rewriteRequestsWithDuplicate 把台账文件的 requests 对象改写为 target 编号
26	// 出现两份记录：第一份保留原记录原文，第二份以 dupKey（JSON 字符串原文，
27	// 可写成转义形式）为键、dupEntry 为值（传 nil 表示与原记录完全相同），其余
28	// 请求记录保持原样。返回改写后的文件内容。标准 map 序列化不可能产生重复键，
29	// 因此这里手工拼接 requests 对象原文。
30	func rewriteRequestsWithDuplicate(t *testing.T, good []byte, target, dupKey string, dupEntry []byte) []byte {
31		t.Helper()
32		var raw struct {
33			Version  int             `json:"version"`
34			Recipes  json.RawMessage `json:"recipes"`
35			Batches  json.RawMessage `json:"batches"`
36			Requests json.RawMessage `json:"requests"`
37		}
38		if err := json.Unmarshal(good, &raw); err != nil {
39			t.Fatal(err)
40		}
41		var reqs map[string]json.RawMessage
42		if err := json.Unmarshal(raw.Requests, &reqs); err != nil {
43			t.Fatal(err)
44		}
45		entry, ok := reqs[target]
46		if !ok {
47			t.Fatalf("正常台账中应存在 %q 请求记录", target)
48		}
49		if dupEntry == nil {
50			dupEntry = entry
51		}
52		var buf bytes.Buffer
53		buf.WriteByte('{')
54		buf.WriteString(strconv.Quote(target))
55		buf.WriteByte(':')
56		buf.Write(entry)
57		buf.WriteByte(',')
58		buf.WriteString(dupKey)
59		buf.WriteByte(':')
60		buf.Write(dupEntry)
61		for k, v := range reqs {
62			if k == target {
63				continue
64			}
65			buf.WriteByte(',')
66			buf.WriteString(strconv.Quote(k))
67			buf.WriteByte(':')
68			buf.Write(v)
69		}
70		buf.WriteByte('}')
71		raw.Requests = buf.Bytes()
