86			t.Fatalf("同一请求编号存在多份记录应返回 ErrCorruptData，得到 %v", err)
87		}
88		if s != nil {
89			s.Close()
90			t.Fatalf("损坏台账不应返回可用的 Store 对象")
91		}
92		msg := err.Error()
93		for _, want := range []string{dupNo, "多份同编号请求记录"} {
94			if !strings.Contains(msg, want) {
95				t.Fatalf("错误信息应包含 %q，得到 %v", want, err)
96			}
97		}
98		got, err := os.ReadFile(filepath.Join(dir, stateFileName))
99		if err != nil {
100			t.Fatal(err)
101		}
102		if !bytes.Equal(got, rejected) {
103			t.Fatalf("拒绝打开不应改动台账文件")
104		}
105	}
106	
107	// 两份保存的成功投料请求被写成同一个编号（操作、提交内容与返回结果完全相同）
108	// 时，打开台账必须返回 ErrCorruptData：不能挑第一份或最后一份继续使用。
109	func TestOpenRejectsDuplicateRequestNoIdenticalRecords(t *testing.T) {
110		dir := t.TempDir()
111		good := setupFeedingAliasLedger(t, dir)
112		bad := rewriteRequestsWithDuplicate(t, good, "feed-1", `"feed-1"`, nil)
113		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
114			t.Fatal(err)
115		}
116		checkDuplicateRequestNoOpen(t, dir, "feed-1", bad)
117	}
118	
119	// 编号是否重复按 JSON 字符串解码后的实际内容判断：第二份记录的键把连字符
120	// 写成 Unicode 转义形式，解码后与 "feed-1" 是同一个编号，同样必须拒绝。
121	func TestOpenRejectsDuplicateRequestNoEscapedKey(t *testing.T) {
