124		// escapedKey 把键中的连字符写成 Unicode 转义形式，解码后与 "feed-1"
125		// 表示同一个编号。
126		escapedKey := `"feed` + "\\u002d" + `1"`
127		bad := rewriteRequestsWithDuplicate(t, good, "feed-1", escapedKey, nil)
128		if !bytes.Contains(bad, []byte(escapedKey)) {
