135	}
136	
137	// 两份同编号记录的内容不同（不同操作、不同提交内容）同样必须拒绝：重复
138	// 判断只看请求编号，与记录内容是否一致无关。
139	func TestOpenRejectsDuplicateRequestNoDifferentContent(t *testing.T) {
140		dir := t.TempDir()
141		good := setupFeedingAliasLedger(t, dir)
142		dup, err := json.Marshal(map[string]string{
143			"op":      "createBatch",
144			"payload": `{"batchNo":"B9","recipeNo":"R1","version":"v1","portions":3}`,
145			"result":  `{"batchNo":"B9"}`,
146		})
147		if err != nil {
148			t.Fatal(err)
149		}
150		bad := rewriteRequestsWithDuplicate(t, good, "feed-1", `"feed-1"`, dup)
151		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
152			t.Fatal(err)
153		}
154		checkDuplicateRequestNoOpen(t, dir, "feed-1", bad)
155	}
156	
157	// 台账正常打开后文件才被改坏（feed-1 的请求记录被写成两份）：下一次查询或
158	// 写入重新读取时必须返回 ErrCorruptData——即使只访问另一个正常批次 B2 也
159	// 不能绕过；被拒绝的重放不得返回任何一份保存结果，被拒绝的新写入不留业务
160	// 记录、不占用请求编号。恢复后原请求各自取回第一次成功的结果，同编号改换
161	// 内容仍返回 ErrRequestConflict，被拒绝过的新编号仍可正常使用。
162	func TestDuplicateRequestNoDetectedOnEveryReload(t *testing.T) {
163		dir := t.TempDir()
164		good := setupFeedingAliasLedger(t, dir)
165		tm := feedingAliasBaseTime()
166	
167		s, err := Open(dir)
168		if err != nil {
169			t.Fatal(err)
170		}
171		defer s.Close()
172	
173		bad := rewriteRequestsWithDuplicate(t, good, "feed-1", `"feed-1"`, nil)
174		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
175			t.Fatal(err)
176		}
177	
178		// 查询损坏批次与另一个正常批次都必须失败，不能沿用此前读到的内容。
179		for _, batchNo := range []string{"B1", "B2"} {
180			v, err := s.GetBatch(batchNo)
181			if !errors.Is(err, ErrCorruptData) {
182				t.Fatalf("损坏未修复时查询批次 %q 应返回 ErrCorruptData，得到 %v", batchNo, err)
183			}
184			if v != nil {
185				t.Fatalf("被拒绝的查询不应返回部分台账视图: %+v", v)
186			}
187		}
188		// 用原编号重放：load 先于幂等重放执行，不能把任何一份同编号记录的结果
189		// 当成第一次成功的结果返回。
190		if _, err := s.AddFeeding("feed-1", "B1", "M1", "1.000", tm, "张三"); !errors.Is(err, ErrCorruptData) {
191			t.Fatalf("重放重复编号请求应先在重新读取时返回 ErrCorruptData，得到 %v", err)
192		}
193		// 对正常批次 B2 的幂等重放与新写入同样不能绕过。
194		if _, err := s.AddFeeding("feed-b2", "B2", "M1", "1.000", tm, "张三"); !errors.Is(err, ErrCorruptData) {
195			t.Fatalf("损坏台账上重放正常批次的请求应返回 ErrCorruptData，得到 %v", err)
196		}
197		if _, err := s.AddFeeding("feed-x", "B2", "M1", "1.000", tm, "钱七"); !errors.Is(err, ErrCorruptData) {
198			t.Fatalf("损坏台账上写入正常批次应返回 ErrCorruptData，得到 %v", err)
199		}
200	
201		// 被拒绝的访问不改动文件，新写入不留下请求记录、不占用请求编号。
202		after, err := os.ReadFile(filepath.Join(dir, stateFileName))
203		if err != nil {
204			t.Fatal(err)
205		}
206		if !bytes.Equal(after, bad) {
207			t.Fatalf("被拒绝的访问不应改动台账文件")
208		}
209		if bytes.Contains(after, []byte("feed-x")) {
210			t.Fatalf("被拒绝的写入不应留下请求记录或占用请求编号")
211		}
212	
213		// 恢复原文件后：两个原请求分别取回各自第一次成功的记录（序号 1、2）；
214		// 同编号改换内容仍是 ErrRequestConflict；被拒绝过的新编号可以正常使用。
215		if err := os.WriteFile(filepath.Join(dir, stateFileName), good, 0o644); err != nil {
216			t.Fatal(err)
217		}
218		r1, err := s.AddFeeding("feed-1", "B1", "M1", "1.000", tm, "张三")
219		if err != nil {
220			t.Fatalf("恢复后重放 feed-1 失败: %v", err)
221		}
222		checkFeedingView(t, r1, 1, "M1", "1", tm, "张三")
223		r2, err := s.AddFeeding("feed-2", "B1", "M1", "1.000", tm, "张三")
224		if err != nil {
225			t.Fatalf("恢复后重放 feed-2 失败: %v", err)
226		}
227		checkFeedingView(t, r2, 2, "M1", "1", tm, "张三")
228		if _, err := s.AddFeeding("feed-1", "B1", "M1", "2.000", tm, "张三"); !errors.Is(err, ErrRequestConflict) {
229			t.Fatalf("同编号改换内容应返回 ErrRequestConflict，得到 %v", err)
230		}
231		r3, err := s.AddFeeding("feed-x", "B1", "M1", "1.000", tm, "张三")
232		if err != nil {
233			t.Fatalf("被拒绝过的请求编号恢复后应可正常使用: %v", err)
234		}
235		checkFeedingView(t, r3, 3, "M1", "1", tm, "张三")
236	}
237	
238	// 没有成功请求记录的正常台账仍可使用：requests 保存为空对象或 null 都不算
239	// 重复，打开、查询与后续写入一切正常。
240	func TestEmptyRequestsObjectStillUsable(t *testing.T) {
241		for name, requests := range map[string]string{
242			"空对象": `{}`,
243			"null": `null`,
244		} {
245			t.Run(name, func(t *testing.T) {
246				dir := t.TempDir()
247				data := []byte(`{"version":1,"recipes":[],"batches":[],"requests":` + requests + `}`)
248				if err := os.WriteFile(filepath.Join(dir, stateFileName), data, 0o644); err != nil {
249					t.Fatal(err)
250				}
251				s, err := Open(dir)
252				if err != nil {
253					t.Fatalf("没有成功请求记录的空台账应能打开: %v", err)
254				}
255				defer s.Close()
256				if _, err := s.GetBatch("B1"); !errors.Is(err, ErrNotFound) {
257					t.Fatalf("空台账查询批次应返回 ErrNotFound，得到 %v", err)
258				}
259				registerStandardRecipe(t, s, "recipe-1")
260				if _, err := s.GetRecipe("R1", "v1"); err != nil {
261					t.Fatalf("空台账应可正常写入并查询: %v", err)
262				}
263			})
264		}
265	}
