package main

import (
	"encoding/json"
	"fmt"
	"strconv"
)

type St struct {
	Version  int            `json:"version"`
	Recipes  map[string]any `json:"recipes"`
	Batches  map[string]any `json:"batches"`
	Requests map[string]int `json:"requests"`
}

func main() {
	variants := []string{
		"requests", "Requests", "REQUESTS", "ReQuEsTs",
		"re-quests", "re_quests", "requests_", "_requests",
		"request", "requestsx",
		"r e q u e s t s",
		`requests`,
		`Requests`,
		`requests`,
	}
	for _, v := range variants {
		raw := `{"version":7,` + strconv.Quote(v) + `:{"hit":1}}`
		// strconv.Quote escapes non-ASCII but keeps unicode as-is; for variants
		// containing backslash-u we want the literal 6 chars preserved as escape:
		// rebuild that case manually.
		if len(v) > 0 && v[0] == 'r' && containsBackslashU(v) {
			raw = `{"version":7,"` + v + `":{"hit":1}}`
		}
		var st St
		err := json.Unmarshal([]byte(raw), &st)
		fmt.Printf("%-16s err=%v version=%d requests=%v recipes=%v\n", v, err, st.Version, st.Requests, st.Recipes)
	}
}

func containsBackslashU(s string) bool {
	for i := 0; i+5 < len(s); i++ {
		if s[i:i+2] == `\u` {
			return true
		}
	}
	return false
}
EOF
